import { publicPlanCopy } from "@/lib/public-plan-copy";
import { PLANS } from "@/lib/plans";
import type { Metadata } from "next";
import { Suspense } from "react";
import Link from "next/link";
import { ArrowRight, Mail, Paperclip, UserRound } from "lucide-react";
import { auth, signIn } from "@/auth";
import { db } from "@/lib/db";
import { redirect } from "next/navigation";
import { Navbar } from "@/components/landing/navbar";
import { BatchProgressCard } from "@/components/landing/batch-progress-card";
import { HowItWorks } from "@/components/landing/how-it-works";
import { Features } from "@/components/landing/features";
import { PricingSection } from "@/components/landing/PricingSection";
import { Footer } from "@/components/landing/footer";
import "@/components/landing/landing.css";
import "@/components/landing/lower-sections.css";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  const copy = await publicPlanCopy();
  const description = `${copy.description} Send a separate, personalized email to each recipient from your own Gmail.`;
  return {
    title: { absolute: "Mailloop — Personalized outreach, made easy" },
    description,
    alternates: { canonical: "/" },
    openGraph: {
      title: "Mailloop — Personalized outreach, made easy",
      description,
      url: "https://www.mailloop.in/",
      siteName: "Mailloop",
      type: "website",
      images: [
        {
          url: "/social-logo.png",
          width: 1024,
          height: 1024,
          alt: "Mailloop logo",
        },
      ],
    },
  };
}

export default async function Home({
  searchParams,
}: {
  searchParams: Promise<{
    error?: string;
    deleted?: string;
    country?: string | string[];
  }>;
}) {
  const session = await auth();
  if (session?.user?.id) {
    const user = await db.user.findUnique({
      where: { id: session.user.id },
      select: { id: true },
    });
    if (user) redirect("/compose");
  }
  const googleSignIn = async () => {
    "use server";
    await signIn("google", { redirectTo: "/compose" });
  };
  const upgradeToPremium = async () => {
    "use server";
    await signIn("google", { redirectTo: "/usage" });
  };
  return (
    <div className="landing min-h-screen [background:var(--landing-bg)] text-[var(--landing-fg)] [font-family:var(--font-sans)] text-[16px] leading-[1.55] overflow-x-clip">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            "@context": "https://schema.org",
            "@type": "WebApplication",
            name: "Mailloop",
            url: "https://www.mailloop.in/",
            description:
              "Mailloop helps job seekers send individual, personalized cold emails from their own Gmail account.",
            applicationCategory: "BusinessApplication",
            operatingSystem: "Web",
            offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
            publisher: { "@type": "Organization", name: "Czar16" },
          }).replace(/</g, "\\u003c"),
        }}
      />
      <Navbar signInAction={googleSignIn} />
      <main
        id="main-content"
        className="landing-container w-full max-w-300 mx-auto [padding-inline:max(20px,_env(safe-area-inset-left))_max(20px,_env(safe-area-inset-right))] [@media(min-width:_640px)]:[padding-inline:max(32px,_env(safe-area-inset-left))_max(32px,_env(safe-area-inset-right))]"
      >
        <section
          className="landing-hero grid items-center"
          aria-labelledby="hero-title"
        >
          <div className="min-w-0">
            <p className="landing-eyebrow [font-family:var(--font-mono)] text-[13px] font-medium uppercase tracking-[0.14em] text-[var(--landing-accent-text)] mb-5.5">
              Personalized outreach, made easy.
            </p>
            <h1
              id="hero-title"
              className="text-[clamp(40px,6vw,72px)] font-extrabold leading-[1.03] tracking-[-0.035em] max-w-[550px]"
            >
              <span className="landing-headline-line block">
                Send up to{" "}
                <span className="landing-gradient-text [background-image:var(--landing-brand-gradient)] [background-clip:text] text-[transparent]">
                  {PLANS.PAID.campaignRecipients}
                </span>
              </span>
              <span className="landing-headline-line block">cold emails</span>
              <span className="landing-headline-line block">
                at{" "}
                <span className="landing-gradient-text [background-image:var(--landing-brand-gradient)] [background-clip:text] text-[transparent]">
                  once.
                </span>
              </span>
            </h1>
            <p className="landing-hero-copy">
              Write once, then send a separate, personalized email to each
              recruiter from your own Gmail. Attach your resume when needed and
              mark replies manually.
            </p>
            <Suspense fallback={null}>
              <AuthFeedback searchParams={searchParams} />
            </Suspense>
            <div className="landing-hero-actions flex items-center">
              <form action={googleSignIn}>
                <button
                  type="submit"
                  className="landing-button inline-flex items-center justify-center gap-3 min-h-13 py-3 px-6 [border:1px_solid_transparent] rounded-full [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] text-[15px] font-semibold cursor-pointer css-hover:shadow-[0_6px_24px_color-mix(in_srgb,_var(--landing-violet)_24%,_transparent)] landing-hero-cta"
                >
                  <span
                    aria-hidden="true"
                    className="landing-google-mark grid size-8.5 shrink-0 place-items-center max-sm:size-7.5"
                  >
                    <span className="block size-7 bg-current [mask:url('/google.svg')_center/contain_no-repeat]" />
                  </span>
                  Get started with Google{" "}
                  <ArrowRight size={18} aria-hidden="true" />
                </button>
              </form>
              <p className="leading-[1.6]">
                Free to start.
                <br className="hidden sm:block" /> Sends from your Gmail.
              </p>
            </div>
            <p className="landing-hero-legal leading-[1.8] text-[var(--landing-faint)] text-[11px] mt-2">
              By signing in, you agree to the{" "}
              <Link href="/terms" className="inline-flex min-h-11 items-center">
                Terms
              </Link>{" "}
              and acknowledge the{" "}
              <Link
                href="/privacy"
                className="inline-flex min-h-11 items-center"
              >
                Privacy Policy
              </Link>
              .
            </p>
            <ul className="landing-hero-highlights">
              <li>
                <span className="landing-highlight-icon">
                  <Mail size={22} aria-hidden="true" />
                </span>
                <span>
                  Use your <br />
                  own Gmail
                </span>
              </li>
              <li>
                <span className="landing-highlight-icon">
                  <UserRound size={22} aria-hidden="true" />
                </span>
                <span>
                  Personalized <br />
                  for each recipient
                </span>
              </li>
              <li>
                <span className="landing-highlight-icon">
                  <Paperclip size={22} aria-hidden="true" />
                </span>
                <span>
                  Your Pdf <br />
                  attached
                </span>
              </li>
            </ul>
          </div>
          <BatchProgressCard />
        </section>
        <div className="outreach-lower text-[var(--tx)] [font-family:var(--font-plus-jakarta),_sans-serif] leading-[1.55] lower-wrap max-w-280 my-0 mx-auto py-0 px-6 max-sm:px-5">
          <HowItWorks />
          <Features />
        </div>
      </main>
      <PricingSection
        upgradeAction={upgradeToPremium}
        startFreeAction={googleSignIn}
        searchParams={searchParams}
      />
      <Footer />
    </div>
  );
}

async function AuthFeedback({
  searchParams,
}: {
  searchParams: Promise<{ error?: string; deleted?: string }>;
}) {
  const { error, deleted } = await searchParams;
  return (
    <>
      {error && (
        <p
          role="alert"
          className="landing-auth-error mt-5 text-[var(--landing-red)] text-[14px]"
        >
          {error === "AccountDeletionPending"
            ? "This Mailloop account is pending deletion. You can’t sign in with this Google account until deletion is complete."
            : "Google sign-in could not complete. Try again and grant Gmail permissions."}
        </p>
      )}
      {deleted === "1" && (
        <p
          role="status"
          className="landing-auth-feedback my-4 text-[var(--landing-muted)] text-[14px]"
        >
          Account deletion requested. You’ve been signed out.
        </p>
      )}
    </>
  );
}
